const entrance=document.querySelector('#entrance');const skip=document.querySelector('#skip');let introDone=false;
function finishIntro(){if(introDone)return;introDone=true;entrance.classList.add('open');skip.hidden=true;window.setTimeout(()=>entrance.remove(),2400)}
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){entrance.remove();skip.hidden=true}else{window.setTimeout(finishIntro,1800);skip.addEventListener('click',finishIntro)}
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));toggle.setAttribute('aria-label',open?'Open menu':'Close menu');nav.classList.toggle('show',!open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('show');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu')}));
